import { type Page, test } from "@playwright/test";

import * as ui from "@e2e/ui-actions";

const FLOW_INTERRUPTED = "Flow ask_library_docs interrupted";
const SUB_AGENT_INTERRUPTED = "Sub-agent library_docs interrupted";

export const triggerFlowInterruptionAndAssertEvents = async (page: Page) => {
  await test.step("Start ask_library_docs flow", async () => {
    await ui.inspectorShell.actions(page).sendMessage("How do I use middleware in Next.js?");
    await ui.conversationLog
      .assertions(page)
      .conversationEventReached("Flow ask_library_docs started");
    await ui.inspectorShell.actions(page).sendMessage("Next.js");
    await ui.inspectorShell.actions(page).sendMessage("middleware setup");
    await ui.conversationLog
      .assertions(page)
      .conversationEventReached("Sub-agent library_docs invoked");
  });

  await test.step("Interrupt with a competing DeepWiki question", async () => {
    await ui.inspectorShell.actions(page).sendMessage("How does routing work in rasaHQ/rasa?");
    await ui.conversationLog
      .assertions(page)
      .conversationEventReached("Flow public_github_repo_info started");
  });

  await test.step("Assert interruption events in log", async () => {
    await ui.conversationLog.assertions(page).conversationEventReached(FLOW_INTERRUPTED);
    await ui.conversationLog.assertions(page).conversationEventReached(SUB_AGENT_INTERRUPTED);
  });
};

export const assertInterruptedFlowInTimeline = async (page: Page) => {
  await test.step("Switch to History view", async () => {
    await ui.viewMenu.actions(page).switchToHistory();
    await ui.historyTimeline.assertions(page).timelineIsVisible();
  });

  await test.step("Assert interrupted status on ask library docs flow", async () => {
    await ui.historyTimeline.assertions(page).itemIsVisible("Ask library docs");
    await ui.historyTimeline.assertions(page).itemHasStatus("Ask library docs", "Interrupted");
  });
};
